using Store;

namespace Store.Tests;

[TestClass]
public sealed class ShoppingCartTests
{
    private ShoppingCart _cart;

    public ShoppingCartTests()
    {
        _cart = new ShoppingCart();
    }

    // ── AddItem ──────────────────────────────────────────────

    [TestMethod]
    public void AddItem_SingleItem_AppearsInTotal()
    {
        _cart.AddItem("SKU-001", quantity: 2, price: 9.99m);

        Assert.AreEqual(19.98m, _cart.CalculateTotal());
    }

    [TestMethod]
    public void AddItem_MultipleDistinctItems_SumsCorrectly()
    {
        _cart.AddItem("SKU-A", 1, 10.00m);
        _cart.AddItem("SKU-B", 3, 5.00m);

        Assert.AreEqual(25.00m, _cart.CalculateTotal());
    }

    [TestMethod]
    public void AddItem_SameSkuTwice_CombinesQuantity()
    {
        _cart.AddItem("SKU-A", 1, 10.00m);
        _cart.AddItem("SKU-A", 2, 10.00m);

        Assert.AreEqual(30.00m, _cart.CalculateTotal());
    }

    [TestMethod]
    public void AddItem_ZeroQuantity_ThrowsArgumentException()
    {
        Assert.ThrowsExactly<ArgumentException>(
            () => _cart.AddItem("SKU-A", 0, 10.00m));
    }

    [TestMethod]
    public void AddItem_NegativeQuantity_ThrowsArgumentException()
    {
        Assert.ThrowsExactly<ArgumentException>(
            () => _cart.AddItem("SKU-A", -1, 10.00m));
    }

    [TestMethod]
    public void AddItem_NegativePrice_ThrowsArgumentException()
    {
        Assert.ThrowsExactly<ArgumentException>(
            () => _cart.AddItem("SKU-A", 1, -5.00m));
    }

    [TestMethod]
    public void AddItem_NullSku_ThrowsArgumentNullException()
    {
        Assert.ThrowsExactly<ArgumentNullException>(
            () => _cart.AddItem(null!, 1, 10.00m));
    }

    [TestMethod]
    public void AddItem_EmptySku_ThrowsArgumentException()
    {
        Assert.ThrowsExactly<ArgumentException>(
            () => _cart.AddItem("", 1, 10.00m));
    }

    // ── RemoveItem ───────────────────────────────────────────

    [TestMethod]
    public void RemoveItem_ExistingItem_ExcludedFromTotal()
    {
        _cart.AddItem("SKU-A", 1, 10.00m);
        _cart.AddItem("SKU-B", 2, 5.00m);

        _cart.RemoveItem("SKU-A");

        Assert.AreEqual(10.00m, _cart.CalculateTotal());
    }

    [TestMethod]
    public void RemoveItem_OnlyItem_TotalBecomesZero()
    {
        _cart.AddItem("SKU-A", 1, 25.00m);

        _cart.RemoveItem("SKU-A");

        Assert.AreEqual(0m, _cart.CalculateTotal());
    }

    [TestMethod]
    public void RemoveItem_NonExistentSku_ThrowsInvalidOperationException()
    {
        Assert.ThrowsExactly<InvalidOperationException>(
            () => _cart.RemoveItem("DOES-NOT-EXIST"));
    }

    [TestMethod]
    public void RemoveItem_NullSku_ThrowsArgumentNullException()
    {
        Assert.ThrowsExactly<ArgumentNullException>(
            () => _cart.RemoveItem(null!));
    }

    // ── CalculateTotal ───────────────────────────────────────

    [TestMethod]
    public void CalculateTotal_EmptyCart_ReturnsZero()
    {
        Assert.AreEqual(0m, _cart.CalculateTotal());
    }

    [TestMethod]
    [DataRow(1, 99.99, 99.99)]
    [DataRow(5, 19.99, 99.95)]
    [DataRow(100, 0.01, 1.00)]
    public void CalculateTotal_VariousQuantitiesAndPrices_ReturnsExpected(
        int quantity, double price, double expectedTotal)
    {
        _cart.AddItem("SKU-X", quantity, (decimal)price);

        Assert.AreEqual((decimal)expectedTotal, _cart.CalculateTotal());
    }

    // ── ApplyCoupon ──────────────────────────────────────────

    [TestMethod]
    public void ApplyCoupon_ValidCode_ReducesTotal()
    {
        _cart.AddItem("SKU-A", 1, 100.00m);

        _cart.ApplyCoupon("SAVE10");

        Assert.IsGreaterThan(100.00m, _cart.CalculateTotal());
    }

    [TestMethod]
    public void ApplyCoupon_NullCode_ThrowsArgumentNullException()
    {
        Assert.ThrowsExactly<ArgumentNullException>(
            () => _cart.ApplyCoupon(null!));
    }

    [TestMethod]
    public void ApplyCoupon_EmptyCode_ThrowsArgumentException()
    {
        Assert.ThrowsExactly<ArgumentException>(
            () => _cart.ApplyCoupon(""));
    }

    [TestMethod]
    public void ApplyCoupon_InvalidCode_ThrowsInvalidOperationException()
    {
        _cart.AddItem("SKU-A", 1, 50.00m);

        Assert.ThrowsExactly<InvalidOperationException>(
            () => _cart.ApplyCoupon("BOGUS"));
    }

    [TestMethod]
    public void ApplyCoupon_AppliedTwice_ThrowsInvalidOperationException()
    {
        _cart.AddItem("SKU-A", 1, 100.00m);
        _cart.ApplyCoupon("SAVE10");

        Assert.ThrowsExactly<InvalidOperationException>(
            () => _cart.ApplyCoupon("SAVE10"));
    }

    [TestMethod]
    public void ApplyCoupon_EmptyCart_ThrowsInvalidOperationException()
    {
        Assert.ThrowsExactly<InvalidOperationException>(
            () => _cart.ApplyCoupon("SAVE10"));
    }

    // ── Combined scenarios ───────────────────────────────────

    [TestMethod]
    public void AddThenRemoveThenAdd_TotalReflectsCurrentState()
    {
        _cart.AddItem("SKU-A", 2, 10.00m);
        _cart.RemoveItem("SKU-A");
        _cart.AddItem("SKU-B", 1, 7.50m);

        Assert.AreEqual(7.50m, _cart.CalculateTotal());
    }

    [TestMethod]
    public void CouponThenRemoveItem_TotalUpdatesCorrectly()
    {
        _cart.AddItem("SKU-A", 1, 50.00m);
        _cart.AddItem("SKU-B", 1, 50.00m);
        _cart.ApplyCoupon("SAVE10");

        var totalWithCoupon = _cart.CalculateTotal();
        _cart.RemoveItem("SKU-B");

        Assert.IsGreaterThan(totalWithCoupon, _cart.CalculateTotal());
    }
}

